# ---------------------------------------------------------------- glyphs
_GCACHE = {}


def glyph_alpha(font, ch):
    """Decode a glyph's 4-bit alpha map to bytes (cached)."""
    key = (id(font), ch)
    got = _GCACHE.get(key)
    if got is not None:
        return got
    _adv, _bx, _by, w, h, b85 = font[ch]
    if not b85:
        _GCACHE[key] = b""
        return b""
    packed = base64.b85decode(b85)
    out = bytearray(w * h)
    for i in range(w * h):
        byte = packed[i // 2]
        out[i] = ((byte >> 4) if i % 2 == 0 else (byte & 15)) * 17
    _GCACHE[key] = bytes(out)
    return _GCACHE[key]


def text_width(s, font, em, size, tracking=0.0):
    """Width in logical px of s set at `size` (logical px em)."""
    scale = size * SS / em
    total = 0.0
    for ch in s:
        g = font.get(ch) or font["?"]
        total += g[0] * scale / SS + tracking
    return total - (tracking if s else 0.0)


def wrap_text(s, font, em, size, max_width, tracking=0.0):
    words = s.split(" ")
    lines = []
    cur = ""
    for word in words:
        trial = word if not cur else cur + " " + word
        if text_width(trial, font, em, size, tracking) <= max_width:
            cur = trial
        else:
            if cur:
                lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


# ---------------------------------------------------------------- canvas
class Canvas:
    """Logical W x H canvas stored at SS supersampling."""

    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.dw = w * SS
        self.dh = h * SS
        self.px = bytearray(bg * self.dw * self.dh)

    def set(self, x, y, color):
        if 0 <= x < self.dw and 0 <= y < self.dh:
            i = (y * self.dw + x) * 3
            self.px[i] = color[0]
            self.px[i + 1] = color[1]
            self.px[i + 2] = color[2]

    def blend(self, x, y, color, a):
        if a <= 0 or not (0 <= x < self.dw and 0 <= y < self.dh):
            return
        if a >= 255:
            self.set(x, y, color)
            return
        i = (y * self.dw + x) * 3
        inv = 255 - a
        self.px[i] = (color[0] * a + self.px[i] * inv) // 255
        self.px[i + 1] = (color[1] * a + self.px[i + 1] * inv) // 255
        self.px[i + 2] = (color[2] * a + self.px[i + 2] * inv) // 255

    def rect(self, x, y, w, h, color):
        x, y, w, h = int(x * SS), int(y * SS), int(w * SS), int(h * SS)
        for yy in range(y, y + h):
            for xx in range(x, x + w):
                self.set(xx, yy, color)

    def frame(self, x, y, w, h, color, t=1):
        self.rect(x, y, w, t, color)
        self.rect(x, y + h - t, w, t, color)
        self.rect(x, y, t, h, color)
        self.rect(x + w - t, y, t, h, color)

    def hline(self, x, y, w, color, t=1):
        self.rect(x, y, w, t, color)

    def vline(self, x, y, h, color, t=1):
        self.rect(x, y, t, h, color)

    def vgrad(self, x, y, w, h, top, bottom):
        """Vertical gradient rectangle (logical coords)."""
        x, y, w, h = int(x * SS), int(y * SS), int(w * SS), int(h * SS)
        for yy in range(y, y + h):
            t = (yy - y) / max(1, h - 1)
            c = (int(top[0] + (bottom[0] - top[0]) * t),
                 int(top[1] + (bottom[1] - top[1]) * t),
                 int(top[2] + (bottom[2] - top[2]) * t))
            for xx in range(x, x + w):
                self.set(xx, yy, c)

    def line(self, x0, y0, x1, y1, color, t=1):
        x0, y0, x1, y1 = int(x0 * SS), int(y0 * SS), int(x1 * SS), int(y1 * SS)
        t = max(1, int(round(t * SS)))
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        x, y = x0, y0
        while True:
            for oy in range(t):
                for ox in range(t):
                    self.set(x + ox, y + oy, color)
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x += sx
            if e2 <= dx:
                err += dx
                y += sy

    def circle(self, cx, cy, r, color):
        cx, cy, r = int(cx * SS), int(cy * SS), int(r * SS)
        for yy in range(cy - r, cy + r + 1):
            for xx in range(cx - r, cx + r + 1):
                if (xx - cx) ** 2 + (yy - cy) ** 2 <= r * r:
                    self.set(xx, yy, color)

    def ring(self, cx, cy, r, color, t=2):
        cx, cy, r, t = int(cx * SS), int(cy * SS), int(r * SS), int(t * SS)
        for yy in range(cy - r, cy + r + 1):
            for xx in range(cx - r, cx + r + 1):
                d = (xx - cx) ** 2 + (yy - cy) ** 2
                if (r - t) ** 2 <= d <= r * r:
                    self.set(xx, yy, color)

    def triangle(self, x0, y0, x1, y1, x2, y2, color):
        self.polygon([(x0, y0), (x1, y1), (x2, y2)], color)

    def polygon(self, pts, color):
        """Scanline polygon fill (logical coords)."""
        pts = [(x * SS, y * SS) for (x, y) in pts]
        miny = int(min(p[1] for p in pts))
        maxy = int(max(p[1] for p in pts))
        n = len(pts)
        for yy in range(miny, maxy + 1):
            nodes = []
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if y0 == y1:
                    continue
                if (yy >= min(y0, y1)) and (yy < max(y0, y1)):
                    nodes.append(x0 + (yy - y0) * (x1 - x0) / (y1 - y0))
            nodes.sort()
            for i in range(0, len(nodes) - 1, 2):
                xa = int(nodes[i])
                xb = int(nodes[i + 1])
                for xx in range(xa, xb + 1):
                    self.set(xx, yy, color)

    # ---- text ----
    def text(self, x, y, s, font, em, asc, size, color, tracking=0.0):
        """Draw text with baseline at logical y; returns x after it."""
        scale = size * SS / em
        cx = x * SS
        baseline = y * SS
        for ch in s:
            g = font.get(ch) or font["?"]
            adv, bx, by, w, h, _b85 = g
            if w and h:
                alpha = glyph_alpha(font, ch)
                gx = cx + bx * scale
                gy = baseline - asc * scale + by * scale
                dw = max(1, int(round(w * scale)))
                dh = max(1, int(round(h * scale)))
                for dy in range(dh):
                    sy = dy / scale
                    iy = int(sy)
                    fy = sy - iy
                    for dx in range(dw):
                        sx = dx / scale
                        ix = int(sx)
                        fx = sx - ix
                        a00 = alpha[iy * w + ix] if iy < h and ix < w else 0
                        a10 = alpha[iy * w + ix + 1] if iy < h and ix + 1 < w else 0
                        a01 = alpha[(iy + 1) * w + ix] if iy + 1 < h and ix < w else 0
                        a11 = alpha[(iy + 1) * w + ix + 1] if iy + 1 < h and ix + 1 < w else 0
                        a = int(a00 * (1 - fx) * (1 - fy) + a10 * fx * (1 - fy)
                                + a01 * (1 - fx) * fy + a11 * fx * fy)
                        if a:
                            self.blend(int(gx) + dx, int(gy) + dy, color, a)
            cx += adv * scale + tracking * SS
        return cx / SS

    def text_center(self, cx, y, s, font, em, asc, size, color,
                    tracking=0.0):
        w = text_width(s, font, em, size, tracking)
        return self.text(cx - w / 2, y, s, font, em, asc, size, color,
                         tracking)

    def text_right(self, right, y, s, font, em, asc, size, color,
                   tracking=0.0):
        w = text_width(s, font, em, size, tracking)
        return self.text(right - w, y, s, font, em, asc, size, color,
                         tracking)

    def para(self, x, y, s, font, em, asc, size, color, max_width,
             leading=None, tracking=0.0):
        """Wrapped paragraph; y is the first baseline; returns y after."""
        if leading is None:
            leading = size * 1.35
        for line in wrap_text(s, font, em, size, max_width, tracking):
            self.text(x, y, line, font, em, asc, size, color, tracking)
            y += leading
        return y

    def downsample(self):
        """Box-filter the supersampled canvas to logical size."""
        out = bytearray(W * H * 3)
        for y in range(H):
            for x in range(W):
                r = g = b = 0
                for oy in range(SS):
                    base = ((y * SS + oy) * self.dw + x * SS) * 3
                    for ox in range(SS):
                        i = base + ox * 3
                        r += self.px[i]
                        g += self.px[i + 1]
                        b += self.px[i + 2]
                n = SS * SS
                j = (y * W + x) * 3
                out[j] = r // n
                out[j + 1] = g // n
                out[j + 2] = b // n
        return out


# ---------------------------------------------------------------- PNG encoder
def png_bytes(raw):
    rows = bytearray()
    stride = W * 3
    for y in range(H):
        rows.append(0)
        start = y * stride
        rows.extend(raw[start:start + stride])
    data = zlib.compress(bytes(rows), 9)

    def chunk(kind, payload):
        out = struct.pack(">I", len(payload)) + kind + payload
        out += struct.pack(">I", zlib.crc32(kind + payload) & 0xFFFFFFFF)
        return out

    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", data) + chunk(b"IEND", b""))


# ---------------------------------------------------------------- illustrations
# Flat editorial vector style: layered silhouettes, muted palette,
# fine gold detail. All three heroes share the same visual language.

def drone(c, cx, cy, s, color):
    """Small quadcopter silhouette."""
    c.rect(cx - s * 0.35, cy - s * 0.12, s * 0.7, s * 0.24, color)
    c.line(cx - s * 0.9, cy - s * 0.3, cx + s * 0.9, cy - s * 0.3, color, 1)
    c.circle(cx - s * 0.9, cy - s * 0.3, s * 0.16, color)
    c.circle(cx + s * 0.9, cy - s * 0.3, s * 0.16, color)
    c.circle(cx, cy + s * 0.05, s * 0.1, color)


def hero_dronewar(c, x, y, w, h):
    """Night schematic: a swarm over Russia, Moscow marked, AWACS above."""
    c.vgrad(x, y, w, h, SKY1, SKY2)
    for sx, sy in [(16, 12), (52, 20), (96, 10), (140, 18), (180, 8),
                   (220, 16), (260, 10), (296, 18)]:
        c.circle(x + sx % w, y + sy, 1, GOLD)
    # Landmass: layered silhouettes with a coastline.
    c.polygon([(x + 28, y + 58), (x + 70, y + 42), (x + 140, y + 38),
               (x + 220, y + 44), (x + 292, y + 56), (x + 292, y + 96),
               (x + 28, y + 96)], TAN)
    c.polygon([(x + 28, y + 78), (x + 90, y + 66), (x + 180, y + 70),
               (x + 292, y + 82), (x + 292, y + 96), (x + 28, y + 96)],
              (140, 124, 94))
    # Sea.
    c.rect(x, y + h - 26, w, 26, SEA)
    # Drone swarm with dotted trails.
    for dx, dy in [(70, 26), (100, 32), (130, 24), (160, 34), (190, 26),
                   (220, 32), (250, 24), (280, 32), (85, 46), (150, 48),
                   (215, 48), (265, 46)]:
        for t in range(1, 5):
            c.circle(x + dx - t * 5, y + dy, 0.7, (200, 208, 220))
        drone(c, x + dx, y + dy, 9, WHITE)
    # Moscow, marked.
    mx, my = x + 208, y + 66
    c.circle(mx, my, 3, GOLD)
    c.ring(mx, my, 8, BURGUNDY, 1.5)
    c.text(mx + 12, my + 3, "MOSCOW", SANSB, SANSB_EM, SANSB_ASC, 8, WHITE,
           tracking=0.8)
    # Poland, left edge: flag + label.
    c.rect(x + 8, y + 66, 18, 5, WHITE)
    c.rect(x + 8, y + 71, 18, 5, BURGUNDY)
    c.text(x + 8, y + 86, "POLAND", SANSB, SANSB_EM, SANSB_ASC, 8, WHITE,
           tracking=0.8)
    # AWACS plane, upper right.
    ax, ay = x + w - 70, y + 60
    c.polygon([(ax, ay + 3), (ax + 26, ay + 3), (ax + 30, ay + 6),
               (ax + 26, ay + 9), (ax, ay + 9)], WHITE)
    c.line(ax + 8, ay + 6, ax + 20, ay - 6, WHITE, 1.5)
    c.line(ax + 8, ay + 6, ax + 20, ay + 16, WHITE, 1.5)
    c.circle(ax + 14, ay - 2, 4, WHITE)
    c.text(ax - 2, ay + 28, "AWACS", SANSB, SANSB_EM, SANSB_ASC, 8, WHITE,
           tracking=0.8)
    # Big 699 badge, bottom left.
    c.rect(x + 10, y + h - 44, 128, 34, BURGUNDY)
    c.text(x + 18, y + h - 19, "699", SERIF, SERIF_EM, SERIF_ASC, 26, WHITE)
    c.text(x + 78, y + h - 27, "DRONES", SANSB, SANSB_EM, SANSB_ASC, 8,
           WHITE, tracking=1.0)
    c.text(x + 78, y + h - 16, "DOWNED", SANSB, SANSB_EM, SANSB_ASC, 8,
           WHITE, tracking=1.0)


def hero_riyadh(c, x, y, w, h):
    """Dusk skyline: the tall tower struck, a drone overhead."""
    c.vgrad(x, y, w, h, DUSK1, DUSK2)
    for sx, sy in [(12, 14), (40, 8), (70, 20), (110, 10), (150, 18),
                   (190, 8), (230, 16), (260, 10), (290, 20)]:
        c.circle(x + sx % w, y + sy, 1, GOLD)
    # Far skyline layer.
    for tx, th in [(6, 52), (44, 68), (252, 62), (290, 44)]:
        c.rect(x + tx, y + h - 20 - th, 24, th + 20, (44, 52, 88))
    # Near skyline layer.
    for tx, th in [(22, 74), (268, 84)]:
        c.rect(x + tx, y + h - 20 - th, 28, th + 20, (34, 42, 72))
        for wy in range(6, th, 10):
            for wx in range(5, 24, 7):
                c.rect(x + tx + wx, y + h - 20 - th + wy, 2, 3, GOLD)
    # The tall tower, centre, stepped crown + antenna.
    tx, th = 122, 92
    c.rect(x + tx, y + h - 20 - th, 64, th + 20, (52, 64, 102))
    c.rect(x + tx + 10, y + h - 20 - th - 8, 44, 8, (52, 64, 102))
    c.rect(x + tx + 30, y + h - 20 - th - 16, 4, 8, (52, 64, 102))
    for wy in range(8, th, 9):
        for wx in range(6, 58, 9):
            c.rect(x + tx + wx, y + h - 20 - th + wy, 3, 4, GOLD)
    # Impact burst at the tower crown.
    bx, by = x + tx + 32, y + h - 20 - th + 2
    c.circle(bx, by, 11, BURGUNDY)
    c.circle(bx, by, 6, GOLD)
    for dx, dy in [(-18, -8), (18, -9), (-15, 9), (19, 7), (0, -14)]:
        c.line(bx, by, bx + dx, by + dy, GOLD, 1.5)
    # Drone, upper right.
    drone(c, x + w - 46, y + 30, 16, INK)
    c.line(x + w - 46, y + 36, x + w - 38, y + 48, GOLD, 1.5)
    # Ground.
    c.rect(x, y + h - 20, w, 20, (24, 30, 54))


def hero_huawei(c, x, y, w, h):
    """Courthouse facade and the scales of justice."""
    c.vgrad(x, y, w, h, (246, 241, 230), CREAM2)
    cx = x + w // 2
    # Pediment + entablature.
    c.triangle(cx - 112, y + 40, cx + 112, y + 40, cx, y + 14, NAVY)
    c.circle(cx, y + 30, 5, GOLD)
    c.rect(x + 40, y + 40, w - 80, 7, NAVY)
    # Columns.
    for i in range(5):
        px = x + 52 + i * 52
        c.rect(px, y + 51, 14, 62, WHITE)
        c.frame(px, y + 51, 14, 62, NAVY, 1)
        c.rect(px - 2, y + 47, 18, 4, NAVY)
        c.rect(px - 2, y + 113, 18, 4, NAVY)
    # Steps.
    c.rect(x + 40, y + 117, w - 80, 6, NAVY)
    c.rect(x + 32, y + 121, w - 64, 5, NAVY2)
    # Scales, centre foreground.
    sx, sy = cx, y + h - 44
    c.rect(sx - 2, sy - 30, 4, 36, INK)
    c.rect(sx - 48, sy - 30, 96, 3, INK)
    c.circle(sx, sy - 32, 4, GOLD)
    c.line(sx - 48, sy - 27, sx - 70, sy - 4, INK, 1.2)
    c.line(sx - 48, sy - 27, sx - 26, sy - 4, INK, 1.2)
    c.line(sx + 48, sy - 27, sx + 26, sy - 4, INK, 1.2)
    c.line(sx + 48, sy - 27, sx + 70, sy - 4, INK, 1.2)
    c.triangle(sx - 80, sy - 4, sx - 16, sy - 4, sx - 48, sy + 9, GOLD)
    c.triangle(sx + 16, sy - 4, sx + 80, sy - 4, sx + 48, sy + 9, GOLD)
    c.rect(sx - 13, sy + 6, 26, 5, INK)
    # Gavel, lower right.
    gx, gy = x + w - 76, y + h - 26
