def draw_map(c, x, y, w, h, pins):
    step_x = w / 64.0
    step_y = h / 28.0
    for r, spans in enumerate(LAND):
        cy = y + (r + 0.5) * step_y
        for lo, hi in spans:
            for col in range(lo, hi + 1):
                cx = x + (col + 0.5) * step_x
                c.circle(cx, cy, 1.6, LANDC)
    # Mediterranean gap (row 8, lat ~35N) so Europe and Africa read
    # apart instead of one blob; UK and Japan are too small for the
    # coarse mask, so they get dots of their own.
    for col in range(30, 38):
        cx = x + (col + 0.5) * step_x
        cy = y + (8 + 0.5) * step_y
        c.circle(cx, cy, 1.8, PAPER)
    for r, col in [(5, 30), (5, 31), (6, 30), (7, 56), (7, 57),
                   (8, 56), (9, 55)]:
        cx = x + (col + 0.5) * step_x
        cy = y + (r + 0.5) * step_y
        c.circle(cx, cy, 1.6, LANDC)
    # The Europe / Middle East pins sit within ~30 px of each other, so
    # their numbers get leader-line labels offset from the true spot.
    LEADER = {1: (8, -24), 2: (4, 24), 5: (-30, -16), 6: (-10, 22),
              7: (-30, -2), 9: (26, -6), 10: (-42, -8), 11: (22, 22)}
    for num, lon, lat in pins:
        px = x + (lon + 180.0) / 360.0 * w
        py = y + (90.0 - lat) / 180.0 * h
        if num in LEADER:
            dx, dy = LEADER[num]
            lx, ly = px + dx, py + dy
            c.circle(px, py, 2.2, BURGUNDY)
            c.line(px, py, lx, ly, BURGUNDY, 0.8)
            c.rect(lx - 7, ly - 7, 14, 14, WHITE)
            c.frame(lx - 7, ly - 7, 14, 14, BURGUNDY, 0.8)
            s = str(num)
            c.text_center(lx, ly + 3.5, s, SANSB, SANSB_EM, SANSB_ASC,
                          8.5, INK)
        else:
            c.circle(px, py, 6, BURGUNDY)
            c.ring(px, py, 6, WHITE, 1)
            c.text_center(px, py + 3.5, str(num), SANSB, SANSB_EM,
                          SANSB_ASC, 8.5, WHITE)


